+++ b/test_changes.sh
@@ -0,0 +1,18 @@
+#!/bin/bash
+# Simple script to verify our changes make logical sense
+echo "Verifying all instances of Rollback error handling were fixed..."
+
+# Count how many instances we fixed
+fixed_count=$(grep -c "if rollbackErr := batch.Rollback()" db.go)
+echo "Fixed $fixed_count instances of ignored Rollback errors"
+
+# Check that we don't have any remaining "_ = batch.Rollback()" 
+remaining_count=$(grep -c "_ = batch.Rollback()" db.go)
+if [ $remaining_count -eq 0 ]; then
+    echo "All instances of ignored Rollback errors have been fixed!"
+else
+    echo "ERROR: Found $remaining_count remaining instances of ignored Rollback errors"
+    exit 1
+fi
+
+echo "Test passed: Error handling for Rollback has been improved"

